/* Numera Academy — Página Missões (problemas de modelagem em três etapas).
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Missões ---------- */
function cases(){return `<div class="wrap page-body">${heading('Missões','Missões de modelagem','Problemas idealizados em três partes: formular a equação, calcular e interpretar o resultado.')}<div class="course-grid cases">${C.CASES.map((c,i)=>{const n=c.tasks.filter((_,j)=>p.completed[`p:${c.id}:${j}`]).length;return `<button type="button" class="course-card mission" data-act="case" data-id="${c.id}"><span class="course-art tint-${i}"><span class="art-glyph">${c.icon}</span><code>${safe(c.expression.split('\n')[0])}</code></span><span class="course-body"><small class="eyebrow">${safe(c.area)}</small><b>${c.title}</b><span class="mission-story">${c.story}</span><small>${method(c.method).title} · ${n}/3 etapas</small><span class="mission-diff">${tierTag(c.method)}${diffStars(world(c.method).stars,'small')}</span>${n?bar(n,3,'Progresso da missão'):''}</span></button>`;}).join('')}</div></div>`;}
function casePage(){const c=C.CASES.find(c=>c.id===s.caseId),i=C.CASES.indexOf(c);return `<div class="player">${playerTop([0,1,2].map(k=>p.completed[`p:${c.id}:${k}`]?'done':k===s.caseQ?'current':''),`Etapa ${s.caseQ+1} de 3`,'nav','data-page="cases"')}<div class="player-body"><div class="player-col"><span class="eyebrow">${safe(c.area)} · ${['Formular','Calcular','Interpretar'][s.caseQ]}</span><h1 class="display small">${c.title}</h1><div class="case-story tint-${i}"><p>${c.story}</p><details><summary>Ver a formulação do modelo</summary><p>${c.model}</p>${btn('Investigar no terminal ↗','case-terminal','text')}</details></div>${btn('Explorar fenômeno relacionado','ex-missao','ghost')}${s.ex.contexto===s.caseId?`<section class="card lt-card"><p class="fine">Experimento complementar com dados próprios; a formulação desta missão permanece acima.</p>${ltAbaFenomenos()}</section>`:''}${question(c.tasks[s.caseQ],`p:${c.id}:${s.caseQ}`,'next-case')}${s.caseQ===2&&s.feedback?.ok?`<div class="callout"><strong>Interpretação do modelo</strong><p>${c.interpret}</p></div>`:''}</div></div></div>`;}


